import { Box, Container, Stack, Typography } from "@mui/material";
import masterData from "../../data/masterData.json";
import { getIcon } from "../../utils/iconMap";
import LeadFormCard from "./LeadFormCard";
import type { Specialty } from "../../types/fellowship";

interface HeroSectionProps {
  specialty?: Specialty | null;
}

export default function HeroSection({ specialty = null }: HeroSectionProps) {
  const { brand, hero } = masterData;

  const headlineBefore = specialty?.headlineBefore || hero.headlineBefore;
  const headlineHighlight = specialty?.headlineHighlight || hero.headlineHighlight;
  const subheadline = specialty?.subheadline || hero.subheadline;
  const description = specialty?.heroDescription || hero.description;
  const fullHeroImage = specialty?.heroImage || hero.image;

  return (
    <Box
      sx={{
        position: "relative",
        overflow: "hidden",
        background: "linear-gradient(180deg, #EAF3FF 0%, #F4F9FF 40%, #FFFFFF 100%)",
        minHeight: { xs: "auto", md: 600, lg: 640 },
      }}
    >
      <Box
        sx={{
          position: "absolute",
          inset: 0,
          opacity: 0.2,
          backgroundImage: "radial-gradient(circle, rgba(0,86,210,0.28) 1px, transparent 1px)",
          backgroundSize: "22px 22px",
          pointerEvents: "none",
        }}
      />

      <Container
        maxWidth="lg"
        sx={{ position: "relative", zIndex: 2, pt: { xs: 2, md: 2.5 }, pb: { xs: 3, md: 0 } }}
      >
        <Stack direction="row" alignItems="center" spacing={1.1} sx={{ mb: { xs: 2.5, md: 2 } }}>
          <Box component="img" src={brand.logo} alt={brand.name} sx={{ width: 34, height: 34 }} />
          <Typography sx={{ fontWeight: 800, fontSize: 14, letterSpacing: "0.08em", color: "#0B1F3A" }}>
            {brand.name}
          </Typography>
        </Stack>

        <Box
          sx={{
            position: "relative",
            display: "grid",
            gridTemplateColumns: {
              xs: "1fr",
              md: "minmax(0, 1fr) minmax(300px, 380px)",
            },
            columnGap: { md: 2, lg: 3 },
            alignItems: "start",
            minHeight: { md: 540, lg: 580 },
          }}
        >
          {/* CENTER doctor image — visible between text & form, NOT under form */}
          <Box
            key={fullHeroImage}
            sx={{
              display: { xs: "none", md: "block" },
              position: "absolute",
              left: "50%",
              bottom: 0,
              transform: "translateX(-55%)",
              width: { md: "48%", lg: "46%" },
              maxWidth: 460,
              height: { md: 520, lg: 560 },
              zIndex: 1,
              pointerEvents: "none",
            }}
          >
            <Box
              component="img"
              src={fullHeroImage}
              alt={specialty?.name || "Fellowship doctor"}
              sx={{
                width: "100%",
                height: "100%",
                objectFit: "cover",
                objectPosition: "center top",
                borderRadius: { md: "24px 24px 0 0" },
              }}
            />
            <Typography
              sx={{
                position: "absolute",
                left: 8,
                top: "32%",
                width: 110,
                fontFamily: "'Dancing Script', cursive",
                fontSize: 18,
                lineHeight: 1.15,
                color: "#0056D2",
                fontWeight: 700,
                transform: "rotate(-10deg)",
                whiteSpace: "pre-line",
                textAlign: "center",
                textShadow: "0 1px 2px rgba(255,255,255,0.9)",
              }}
            >
              {hero.scriptText}
            </Typography>
          </Box>

          {/* LEFT text */}
          <Box sx={{ position: "relative", zIndex: 3, maxWidth: { md: 420, lg: 460 }, pt: { md: 0.5 } }}>
            <Typography
              sx={{
                color: "#0056D2",
                fontWeight: 700,
                fontSize: 11,
                letterSpacing: "0.14em",
                mb: 1.5,
              }}
            >
              {specialty ? specialty.name.toUpperCase() : brand.eyebrow}
            </Typography>

            <Typography
              component="h1"
              sx={{
                fontWeight: 800,
                color: "#0B1F3A",
                fontSize: { xs: "1.7rem", sm: "2.05rem", md: "2.25rem", lg: "2.45rem" },
                lineHeight: 1.15,
                mb: 1.5,
                letterSpacing: "-0.02em",
              }}
            >
              {headlineBefore}
              <Box component="span" sx={{ color: "#0056D2" }}>
                {headlineHighlight}
              </Box>
            </Typography>

            <Typography sx={{ fontWeight: 700, color: "#0B1F3A", fontSize: { xs: 15, md: 16.5 }, mb: 1.25 }}>
              {subheadline}
            </Typography>

            <Typography
              sx={{ color: "#5A6B80", fontSize: { xs: 13.5, md: 14.5 }, lineHeight: 1.7, mb: 3, maxWidth: 400 }}
            >
              {description}
            </Typography>

            {/* Mobile: center doctor */}
            <Box
              sx={{
                display: { xs: "flex", md: "none" },
                justifyContent: "center",
                mb: 2.5,
              }}
            >
              <Box
                component="img"
                key={`m-${fullHeroImage}`}
                src={fullHeroImage}
                alt="Doctor"
                sx={{
                  width: "78%",
                  maxWidth: 300,
                  height: 340,
                  objectFit: "cover",
                  objectPosition: "center top",
                  borderRadius: 3,
                }}
              />
            </Box>

            <Stack
              direction="row"
              flexWrap="wrap"
              useFlexGap
              spacing={{ xs: 2, md: 2.25 }}
              alignItems="center"
              sx={{ mb: 2 }}
            >
              {hero.stats.map((stat) => {
                const Icon = getIcon(stat.icon);
                return (
                  <Stack key={stat.id} direction="row" spacing={0.9} alignItems="center">
                    <Box
                      sx={{
                        width: 34,
                        height: 34,
                        borderRadius: "50%",
                        bgcolor: "#E8F1FF",
                        display: "flex",
                        alignItems: "center",
                        justifyContent: "center",
                      }}
                    >
                      <Icon sx={{ color: "#0056D2", fontSize: 18 }} />
                    </Box>
                    <Typography sx={{ fontSize: 12.5, fontWeight: 700, color: "#0B1F3A" }}>
                      {stat.value ? (
                        <>
                          <Box component="span" sx={{ color: "#0056D2" }}>
                            {stat.value}
                          </Box>{" "}
                          {stat.label}
                        </>
                      ) : (
                        stat.label
                      )}
                    </Typography>
                  </Stack>
                );
              })}
            </Stack>

            <Stack
              direction="row"
              alignItems="center"
              spacing={1.25}
              sx={{
                display: "inline-flex",
                bgcolor: "#fff",
                border: "1px solid #E0EAF6",
                borderRadius: "12px",
                px: 1.5,
                py: 0.9,
                boxShadow: "0 4px 16px rgba(0,86,210,0.08)",
                mb: { md: 3 },
              }}
            >
              <Box component="img" src={hero.cpdBadge} alt="CPD" sx={{ width: 38, height: 38 }} />
              <Box>
                <Typography sx={{ fontSize: 12, fontWeight: 700, color: "#0B1F3A" }}>
                  {hero.cpdLabel}
                </Typography>
                {hero.cpdSubLabel && (
                  <Typography sx={{ fontSize: 10, color: "#6B7C93" }}>{hero.cpdSubLabel}</Typography>
                )}
              </Box>
            </Stack>
          </Box>

          {/* RIGHT form — above image layer, doctor stays center/left of form */}
          <Box
            sx={{
              position: "relative",
              zIndex: 4,
              display: "flex",
              justifyContent: { xs: "stretch", md: "flex-end" },
              alignItems: "flex-start",
              pt: { md: 0.5 },
              pb: { md: 3 },
            }}
          >
            <LeadFormCard key={specialty?.id || "default"} defaultSpecialty={specialty?.id || ""} />
          </Box>
        </Box>
      </Container>
    </Box>
  );
}
